gPB(){return"\u09b8\u09be\u09ae\u099e\u09cd\u099c\u09b8\u09cd\u09af\u09c7\u09b0 \u099c\u09a8\u09cd\u09af \u09b8\u09cd\u099f\u0995, \u09b2\u09c7\u099c\u09be\u09b0 \u098f\u09ac\u0982 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u0995\u09cb\u09a1 \u09aa\u09b0\u09c0\u0995\u09cd\u09b7\u09be \u0995\u09b0\u09c1\u09a8 \u2014 \u098f\u09ac\u0982 \u09af\u09be \u09a0\u09bf\u0995 \u0995\u09b0\u09be \u09a8\u09bf\u09b0\u09be\u09aa\u09a6 \u09a4\u09be \u09ae\u09c7\u09b0\u09be\u09ae\u09a4 \u0995\u09b0\u09c1\u09a8"},
gPm(){return"\u0995\u09c7 \u0995\u09c0 \u0995\u09b0\u09c7\u099b\u09c7 \u2014 \u099a\u09be\u09b2\u09be\u09a8, \u09aa\u09c7\u09ae\u09c7\u09a8\u09cd\u099f, \u09ad\u09be\u0989\u099a\u09be\u09b0, \u09aa\u09bf\u09b0\u09bf\u09af\u09bc\u09a1 \u09b2\u0995 \u098f\u09ac\u0982 \u0985\u09cd\u09af\u09be\u0995\u09be\u0989\u09a8\u09cd\u099f \u09aa\u09b0\u09bf\u09ac\u09b0\u09cd\u09a4\u09a8"},
gPC(){return"\u09ac\u09c7\u09a4\u09a8, \u0985\u0997\u09cd\u09b0\u09bf\u09ae, \u098f\u09ac\u0982 \u09ae\u09be\u09b8\u09bf\u0995 \u09aa\u09c7\u09b0\u09cb\u09b2"},
gPM(){return"\u09ad\u09c1\u09b2\u09ac\u09b6\u09a4 \u09a6\u09c1\u0987\u09ac\u09be\u09b0 \u09aa\u09cd\u09b0\u09ac\u09c7\u09b6 \u0995\u09b0\u09be\u09a8\u09cb \u09a6\u09c1\u099f\u09bf \u0997\u09cd\u09b0\u09be\u09b9\u0995 \u09ac\u09be \u09b8\u09b0\u09ac\u09b0\u09be\u09b9\u0995\u09be\u09b0\u09c0 \u09b0\u09c7\u0995\u09b0\u09cd\u09a1 \u098f\u0995\u09a4\u09cd\u09b0\u09bf\u09a4 \u0995\u09b0\u09c1\u09a8"},
gPI(){return"\u09b8\u09cd\u09a5\u09be\u09af\u09bc\u09c0 \u09b8\u09ae\u09cd\u09aa\u09a6"},
