gVs(){return"\u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09ae\u09c1\u09a6\u09cd\u09b0\u09bf\u09a4 \u09a8\u09a5\u09bf\u09b0 \u0995\u09cd\u09b7\u09c7\u09a4\u09cd\u09b0\u09c7 \u09aa\u09cd\u09b0\u09af\u09cb\u099c\u09cd\u09af \u2014 \u099a\u09be\u09b2\u09be\u09a8, \u0989\u09a6\u09cd\u09a7\u09c3\u09a4\u09bf, \u0995\u09cd\u09b0\u09af\u09bc \u0986\u09a6\u09c7\u09b6\u0964"},
gVG(){return"\u09b6\u09ac\u09cd\u09a6\u09c7 \u09aa\u09b0\u09bf\u09ae\u09be\u09a3 \u09a6\u09c7\u0996\u09be\u09a8"},
gVH(){return"\u09ac\u09cd\u09af\u09be\u0982\u0995 \u09ac\u09bf\u09ac\u09b0\u09a3 \u09ac\u0995\u09cd\u09b8 \u09a6\u09c7\u0996\u09be\u09a8"},
