gVx(){return"\u0924\u0924\u094d\u0915\u093e\u0932 \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u0923 \u0915\u0947 \u0932\u093f\u090f \u0906\u092a\u0915\u093e \u092b\u0935\u0930\u093e\u0928 \u0906\u0908\u0921\u0940 / QR \u0938\u0902\u0926\u0930\u094d\u092d"},
gVu(){return"\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092b\u093c\u0949\u0928\u094d\u091f"},
gJF(){return"\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u0915\u093e \u0909\u092d\u093e\u0930 \u0930\u0902\u0917"},
gJH(){return"\u091f\u0948\u0917\u0932\u093e\u0907\u0928 \u0930\u0902\u0917"},
gVK(){return"\u0939\u0930 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u092a\u0930 \u0906\u092a\u0915\u0947 \u0928\u093e\u092e \u0915\u0947 \u0928\u0940\u091a\u0947 \u091b\u092a\u093e"},
gVJ(){return"\u0906\u092a\u0915\u0947 \u092e\u0941\u0926\u094d\u0930\u093f\u0924 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c\u094b\u0902 \u092a\u0930 \u0939\u0930 \u091f\u0947\u092c\u0932/\u092c\u0949\u0915\u094d\u0938 \u092c\u0949\u0930\u094d\u0921\u0930 \u0915\u0947 \u0932\u093f\u090f \u092d\u0940 \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948 \u2014 \u092a\u094d\u0930\u093f\u0902\u091f \u0932\u0947\u0906\u0909\u091f \u0938\u094d\u0935\u092f\u0902 \u0915\u092d\u0940 \u0928\u0939\u0940\u0902 \u092c\u0926\u0932\u0924\u093e, \u0915\u0947\u0935\u0932 \u092f\u0939 \u090f\u0915 \u0930\u0902\u0917\u0964"},
gJI(){return"\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u0930\u0902\u0917"},
gVN(){return"\u0906\u0907\u091f\u092e \u0935\u093f\u0935\u0930\u0923, \u092a\u0924\u0947, \u0930\u093e\u0936\u093f\u092f\u093e\u0902 \u0914\u0930 \u0905\u0928\u094d\u092f \u092e\u0941\u0916\u094d\u092f \u092a\u093e\u0920"},
gVD(){return"\u0915\u0902\u092a\u0928\u0940 / \u0926\u0941\u0915\u093e\u0928 \u0915\u093e \u0928\u093e\u092e \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u0948\u0964"},
gVq(){return"\u0905\u092a\u0928\u0940 \u0915\u0902\u092a\u0928\u0940 \u0915\u093e \u0932\u094b\u0917\u094b \u091a\u0941\u0928\u0947\u0902"},
gV9(){return"\u0907\u0938 \u0930\u0902\u0917 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902"},
gTJ(){return"\u0916\u093e\u0924\u093e \u0932\u0947\u092c\u0932"},
gJn(){return"\u092c\u0948\u0902\u0915 \u0915\u093e \u0928\u093e\u092e (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gJl(){return"\u0916\u093e\u0924\u093e \u0938\u0902\u0916\u094d\u092f\u093e (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gJp(){return"IBAN (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gTK(){return'\u0916\u093e\u0924\u093e \u0932\u0947\u092c\u0932 (\u091c\u0948\u0938\u0947 "ADCB Current")'},
gTV(){return"\u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u0936\u0947\u0937"},
ga30(){return'\u091c\u0948\u0938\u0947 "\u092b\u094d\u0930\u0902\u091f \u0921\u0947\u0938\u094d\u0915 \u092b\u094d\u0932\u094b\u091f"'},
ga2Y(){return"\u0905\u092d\u093f\u0930\u0915\u094d\u0937\u0915 (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
ga36(){return"\u092a\u094d\u0930\u093e\u0930\u0902\u092d\u093f\u0915 \u092b\u094d\u0932\u094b\u091f"},
gMJ(){return"\u0930\u093e\u0936\u093f"},
ga2V(){return"\u0936\u094d\u0930\u0947\u0923\u0940"},
ga35(){return"\u0928\u094b\u091f (\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915)"},
gXU(){return"\u092a\u0941\u0937\u094d\u091f\u093f \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f RESET \u091f\u093e\u0907\u092a \u0915\u0930\u0947\u0902"},
gXN(){return"\u0938\u092c \u0915\u0941\u091b \u092e\u093f\u091f\u093e\u090f\u0902"},
XT(a){return"\u0930\u0940\u0938\u0947\u091f \u0935\u093f\u092b\u0932: "+a},
gXR(){return"\u0938\u092d\u0940 \u0921\u0947\u091f\u093e \u0930\u0940\u0938\u0947\u091f \u0915\u0930\u0947\u0902?"},
gXO(){return"\u092f\u0939 \u0938\u091a\u092e\u0941\u091a \u0935\u0939 \u0938\u092c \u0915\u0941\u091b \u092e\u093f\u091f\u093e \u0926\u0947\u0924\u093e \u0939\u0948 \u091c\u094b \u0935\u094d\u092f\u0935\u0938\u093e\u092f \u0928\u0947 \u0915\u092d\u0940 \u0926\u0930\u094d\u091c \u0915\u093f\u092f\u093e \u092f\u093e \u0906\u092f\u093e\u0924 \u0915\u093f\u092f\u093e \u0939\u0948: \u0939\u0930 \u0917\u094d\u0930\u093e\u0939\u0915, \u0906\u092a\u0942\u0930\u094d\u0924\u093f\u0915\u0930\u094d\u0924\u093e, \u0906\u0907\u091f\u092e, \u091a\u093e\u0932\u093e\u0928, \u0916\u0930\u0940\u0926, \u0928\u094b\u091f, \u091a\u0947\u0915, \u0921\u093f\u0932\u0940\u0935\u0930\u0940, \u0935\u093e\u0909\u091a\u0930, \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f, \u0938\u094d\u091f\u0949\u0915 \u092e\u0942\u0935\u092e\u0947\u0902\u091f, \u092c\u0948\u0902\u0915 \u0916\u093e\u0924\u093e, \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940, \u0914\u0930 \u0911\u0921\u093f\u091f \u0932\u0949\u0917\u0964\n\n\u0915\u0947\u0935\u0932 \u0936\u093e\u0916\u093e(\u090f\u0902), \u0915\u0902\u092a\u0928\u0940 \u092a\u094d\u0930\u094b\u092b\u093c\u093e\u0907\u0932, \u0914\u0930 \u0938\u094d\u091f\u093e\u092b \u0932\u0949\u0917\u093f\u0928 \u092c\u091a\u0924\u0947 \u0939\u0948\u0902 \u2014 \u0924\u093e\u0915\u093f \u0906\u092a \u0905\u092d\u0940 \u092d\u0940 \u0910\u092a \u092e\u0947\u0902 \u0935\u093e\u092a\u0938 \u0906 \u0938\u0915\u0947\u0902\u0964 \u092c\u093e\u0915\u0940 \u0938\u092c \u0915\u0941\u091b \u0916\u093e\u0932\u0940 \u0935\u093e\u092a\u0938 \u0906\u0924\u093e \u0939\u0948, \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u090f\u0915 \u092c\u093f\u0932\u094d\u0915\u0941\u0932 \u0928\u0908 \u0915\u0902\u092a\u0928\u0940 \u0915\u0940 \u0924\u0930\u0939\u0964\n\n\u0907\u0938\u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0926\u094b\u092c\u093e\u0930\u093e \u091a\u0932\u093e\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u090f\u0915 \u0921\u0941\u092a\u094d\u0932\u093f\u0915\u0947\u091f \u092f\u093e \u092c\u093f\u0917\u0921\u093c\u0947 \u0939\u0941\u090f \u0906\u092f\u093e\u0924 \u0915\u094b \u0938\u093e\u092b \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u0930\u0947\u0902\u0964 \u0907\u0938\u0947 \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e\u0964"},
